// api/create-household-invite.js
//
// Household/partner sharing is a Premium feature — see the priority
// to-do list, "Feature gating". Generating an invite code is the one
// clear choke point for this: once someone holds a valid code,
// joinHousehold() itself doesn't need its own Premium check, since a
// code could only ever have been generated by an already-Premium
// household in the first place.
//
// This runs the exact same insert household.js's old client-side
// createInvite() used to do directly against Supabase — the only change
// is that it now happens here, server-side, behind requirePremiumUser,
// so a Free household can no longer create one at all (previously
// possible for anyone who called the Supabase client directly, since
// there was no premium check anywhere in that path).

import { createClient } from "@supabase/supabase-js";
import { requirePremiumUser } from "./_lib/requirePremiumUser.js";

const supabaseAdmin = createClient((process.env.SUPABASE_URL || "").trim(), (process.env.SUPABASE_SERVICE_ROLE_KEY || "").trim());

export default async function handler(req, res) {
  res.setHeader("Access-Control-Allow-Origin", "https://localhost");
  res.setHeader("Access-Control-Allow-Methods", "POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Authorization, Content-Type");
  if (req.method === "OPTIONS") {
    return res.status(204).end();
  }
  if (req.method !== "POST") {
    return res.status(405).json({ error: "Method not allowed" });
  }

  const session = await requirePremiumUser(req, res);
  if (!session.ok) return; // requirePremiumUser has already sent the 401/402/404 response

  const { data, error } = await supabaseAdmin
    .from("household_invites")
    .insert({ household_id: session.householdId, created_by: session.userId })
    .select("code, expires_at")
    .single();

  if (error) {
    console.error("create-household-invite error:", error);
    return res.status(500).json({ error: "Couldn't create an invite." });
  }

  return res.status(200).json(data);
}
